class MarkdownParser:
    """
    将 Markdown 文本解析为结构化块（文本、表格、图像、列表）。
    适用于转换为 Excel 等结构化格式。
    """
    def __init__(self):
        self.md_parser = MarkdownIt('gfm-like').enable(['strikethrough', 'table'])

    def parse(self, md_content: str) -> list:
        """主解析流程：解析 Token -> 递归处理块 -> 合并文本 -> 合并连表"""
        tokens = self.md_parser.parse(md_content)
        token_iterator = iter(tokens)
        blocks = self._parse_tokens_recursively(token_iterator)
        blocks = self._merge_text_blocks(blocks)
        blocks = self._merge_continued_tables(blocks)
        return blocks

    def _parse_tokens_recursively(self, token_iterator: iter, stop_tokens: set = None) -> list:
        blocks = []
        for token in token_iterator:
            if stop_tokens and token.type in stop_tokens:
                return blocks

            if token.type == 'table_open':
                table_tokens = [token]
                for t in token_iterator:
                    table_tokens.append(t)
                    if t.type == 'table_close':
                        break
                
                df, alignments = self._parse_table_tokens_to_df(table_tokens)
                if not df.empty or df.columns.size > 0:
                    blocks.append(('table', df, alignments))

            elif token.type == 'fence':
                blocks.append(('code', token.content.strip()))
                
            elif token.type == 'heading_open':
                inline_token = next(token_iterator, None)
                next(token_iterator, None) # consume heading_close
                if inline_token:
                    content = inline_token.content.strip()
                    level = int(token.tag[1:])
                    blocks.append(('heading', level, content))
                
            elif token.type == 'hr':
                blocks.append(('hr',))

            elif token.type == 'blockquote_open':
                nested_blocks = self._parse_tokens_recursively(token_iterator, stop_tokens={'blockquote_close'})
                blocks.append(('blockquote', nested_blocks))

            elif token.type == 'bullet_list_open' or token.type == 'ordered_list_open':
                list_type = 'bullet' if token.type == 'bullet_list_open' else 'ordered'
                start_num = int(token.attrs.get('start', 1))
                item_counter = start_num
                
                nested_blocks = self._parse_tokens_recursively(token_iterator, stop_tokens={'bullet_list_close', 'ordered_list_close'})
                
                for item in nested_blocks:
                    if item[0] == 'list_item':
                        item_level, item_content = item[1], item[2]
                        blocks.append(('list_item', item_level, list_type, item_counter, item_content))
                        if list_type == 'ordered':
                            item_counter += 1

            elif token.type == 'list_item_open':
                level = token.level
                nested_content = self._parse_tokens_recursively(token_iterator, stop_tokens={'list_item_close'})
                blocks.append(('list_item', level, nested_content))

            elif token.type == 'paragraph_open':
                inline_token = next(token_iterator, None)
                next(token_iterator, None) # consume paragraph_close

                if inline_token and inline_token.children:
                    is_image = False
                    for child in inline_token.children:
                        if child.type == 'image':
                            is_image = True
                            alt = "".join([t.content for t in child.children] if child.children else [])
                            src = child.attrs.get('src', '')
                            blocks.append(('image', alt, src))
                            break
                    if not is_image:
                        content = inline_token.content.strip()
                        if content:
                            blocks.append(('text', content))
                elif inline_token:
                    content = inline_token.content.strip()
                    if content:
                        blocks.append(('text', content))
        return blocks
    
    def _merge_text_blocks(self, blocks: list) -> list:
        merged_blocks = []
        text_buffer = []
        for block in blocks:
            if block[0] == 'text':
                text_buffer.append(block[1])
            else:
                if text_buffer:
                    merged_blocks.append(('text', '\\n'.join(text_buffer)))
                    text_buffer = []
                merged_blocks.append(block)
        if text_buffer:
            merged_blocks.append(('text', '\\n'.join(text_buffer)))
        return merged_blocks

    def _merge_continued_tables(self, blocks: list) -> list:
        new_blocks = []
        temp_tables = []
        separator_pattern = re.compile(r'^\s*\*{3,}\s*continued\s*\.{3,}\s*\*{3,}\s*$', re.IGNORECASE)

        for block in blocks:
            is_table = block[0] == 'table'
            if is_table:
                temp_tables.append(block)
            elif block[0] == 'text' and separator_pattern.match(block[1].strip()):
                continue
            else:
                if temp_tables:
                    if len(temp_tables) > 1:
                        all_dfs = [t[1] for t in temp_tables]
                        first_df_cols = all_dfs[0].shape[1]
                        if all(df.shape[1] == first_df_cols for df in all_dfs):
                            header = all_dfs[0].columns
                            for i in range(1, len(all_dfs)):
                                all_dfs[i].columns = header
                            merged_df = pd.concat(all_dfs, ignore_index=True)
                            new_blocks.append(('table', merged_df, temp_tables[0][2]))
                        else:
                            new_blocks.extend(temp_tables)
                    else:
                        new_blocks.append(temp_tables[0])
                    temp_tables = []
                new_blocks.append(block)

        if temp_tables:
            if len(temp_tables) > 1:
                all_dfs = [t[1] for t in temp_tables]
                first_df_cols = all_dfs[0].shape[1]
                if all(df.shape[1] == first_df_cols for df in all_dfs):
                    header = all_dfs[0].columns
                    for i in range(1, len(all_dfs)):
                        all_dfs[i].columns = header
                    merged_df = pd.concat(all_dfs, ignore_index=True)
                    new_blocks.append(('table', merged_df, temp_tables[0][2]))
                else:
                    new_blocks.extend(temp_tables)
            else:
                new_blocks.append(temp_tables[0])
        return new_blocks
    
    def _parse_table_tokens_to_df(self, table_tokens: list) -> tuple:
        header = []
        alignments = []
        rows = []
        current_row = []
        in_header = False

        for i, token in enumerate(table_tokens):
            if token.type == 'thead_open': in_header = True
            elif token.type == 'thead_close': in_header = False
            elif token.type == 'tr_open': current_row = []
            elif token.type == 'tr_close':
                if current_row:
                    if in_header:
                        header = [str(c) for c in current_row]
                    else:
                        rows.append(current_row)
            elif token.type == 'th_open' or token.type == 'td_open':
                inline_token = table_tokens[i+1]
                current_row.append(inline_token.content)
                if in_header and token.type == 'th_open':
                    style = token.attrs.get('style', '')
                    if 'text-align:center' in style: alignments.append('center')
                    elif 'text-align:right' in style: alignments.append('right')
                    else: alignments.append('left')
        
        if header and all(not h for h in header):
            if rows:
                new_header_raw = rows.pop(0)
                header = [re.sub(r'[*_`~]', '', h).strip() for h in new_header_raw]

        df = pd.DataFrame()
        try:
            if not header and rows:
                df = pd.DataFrame(rows)
            elif header:
                while len(alignments) < len(header):
                    alignments.append('left')
                for i, row_data in enumerate(rows):
                    while len(row_data) < len(header):
                        row_data.append('')
                    if len(row_data) > len(header):
                        rows[i] = row_data[:len(header)]
                df = pd.DataFrame(rows, columns=header)
        except Exception:
            return pd.DataFrame(), []

        return df, alignments

